import sys
def solve(n, q, queries):
    if q == 0: return ""
    parent = list(range(n + 1))
    size = [1] * (n + 1)
    history = []

    def find(i):
        while i != parent[i]: i = parent[i]
        return i

    def union(i, j):
        root_i, root_j = find(i), find(j)
        if root_i != root_j:
            if size[root_i] < size[root_j]: root_i, root_j = root_j, root_i
            parent[root_j] = root_i
            size[root_i] += size[root_j]
            history.append((root_j, root_i))
            return True
        return False

    def rollback(count):
        while count > 0:
            count -= 1
            if history:
                j, i = history.pop()
                size[i] -= size[j]
                parent[j] = j

    tree = [[] for _ in range(4 * q + 1)]
    def add_edge_to_tree(node, l, r, ql, qr, u, v):
        if ql > r or qr < l: return
        if ql <= l and r <= qr:
            tree[node].append((u, v))
            return
        mid = (l + r) // 2
        add_edge_to_tree(2 * node, l, mid, ql, qr, u, v)
        add_edge_to_tree(2 * node + 1, mid + 1, r, ql, qr, u, v)

    active_edges = {}
    query_times = []
    for t in range(q):
        type_, u, v = queries[t]
        if u > v: u, v = v, u
        if type_ == 1: active_edges[(u, v)] = t
        elif type_ == 2:
            if (u, v) in active_edges:
                start_time = active_edges.pop((u, v))
                add_edge_to_tree(1, 0, q - 1, start_time, t - 1, u, v)
        elif type_ == 3: query_times.append((t, u, v))

    for (u, v), start_time in active_edges.items():
        add_edge_to_tree(1, 0, q - 1, start_time, q - 1, u, v)

    queries_by_time = [[] for _ in range(q)]
    for t, u, v in query_times:
        queries_by_time[t].append((u, v))

    out = []
    def dfs_evaluate(node, l, r):
        unions_done = 0
        for u, v in tree[node]:
            if union(u, v): unions_done += 1

        if l == r:
            for u, v in queries_by_time[l]:
                out.append("1" if find(u) == find(v) else "0")
        else:
            mid = (l + r) // 2
            dfs_evaluate(2 * node, l, mid)
            dfs_evaluate(2 * node + 1, mid + 1, r)

        rollback(unions_done)

    dfs_evaluate(1, 0, q - 1)
    return "".join(out)

if __name__ == '__main__':
    input_data = sys.stdin.read().split()
    if not input_data: exit()
    n, q = int(input_data[0]), int(input_data[1])
    queries = []
    idx = 2
    for _ in range(q):
        queries.append((int(input_data[idx]), int(input_data[idx+1]), int(input_data[idx+2])))
        idx += 3
    print(solve(n, q, queries))

